import numpy as np
import matplotlib.pyplot as plt

from mpl_toolkits.mplot3d.art3d import Poly3DCollection


# ============================================================
# USER PARAMETERS
# ============================================================

# Input files generated by TPMSgen.py
NODE_FILE = "primitive_nodes.csv"
ELEMENT_FILE = "primitive_elements.csv"
NORMAL_FILE = "primitive_normals.csv"

# Unit-cell dimensions
Lx = 1.0
Ly = 1.0
Lz = 1.0

# Shell thickness
THICKNESS = 0.02

# Material properties
E = 210.0e9
NU = 0.30
RHO = 7850.0

# Numerical tolerances
BOUNDARY_TOL = 1.0e-6
AREA_TOL = 1.0e-12


# ============================================================
# VISUALIZATION OPTIONS
# ============================================================

SHOW_MESH = True

# Show nodal points
SHOW_NODES = False

# Show triangular element edges
SHOW_ELEMENT_EDGES = True

# Transparency of shell surface
MESH_ALPHA = 0.70

# Element edge thickness
EDGE_LINEWIDTH = 0.25

# Node marker size
NODE_SIZE = 2.0

# Initial camera orientation
VIEW_ELEVATION = 25.0
VIEW_AZIMUTH = 45.0


# ============================================================
# OUTPUT FILES
# ============================================================

OUTPUT_NODE_FILE = "fem_nodes.csv"
OUTPUT_ELEMENT_FILE = "fem_elements.csv"
OUTPUT_ELEMENT_DATA_FILE = "fem_element_data.csv"

OUTPUT_XMIN = "boundary_xmin.csv"
OUTPUT_XMAX = "boundary_xmax.csv"

OUTPUT_YMIN = "boundary_ymin.csv"
OUTPUT_YMAX = "boundary_ymax.csv"

OUTPUT_ZMIN = "boundary_zmin.csv"
OUTPUT_ZMAX = "boundary_zmax.csv"


# ============================================================
# READ NODE DATA
# ============================================================

def read_nodes(filename):
    """
    Read nodal coordinates.

    Expected format:

    NodeID,X,Y,Z
    """

    data = np.loadtxt(
        filename,
        delimiter=",",
        skiprows=1
    )

    node_ids = data[:, 0].astype(int)
    nodes = data[:, 1:4]

    return node_ids, nodes


# ============================================================
# READ ELEMENT DATA
# ============================================================

def read_elements(filename):
    """
    Read triangular shell connectivity.

    Expected format:

    ElementID,Node1,Node2,Node3
    """

    data = np.loadtxt(
        filename,
        delimiter=",",
        skiprows=1
    )

    element_ids = data[:, 0].astype(int)
    elements = data[:, 1:4].astype(int)

    return element_ids, elements


# ============================================================
# READ NORMAL DATA
# ============================================================

def read_normals(filename):
    """
    Read analytical nodal normals.

    Expected format:

    NodeID,Nx,Ny,Nz
    """

    data = np.loadtxt(
        filename,
        delimiter=",",
        skiprows=1
    )

    normal_node_ids = data[:, 0].astype(int)
    normals = data[:, 1:4]

    return normal_node_ids, normals


# ============================================================
# CHECK NODE NUMBERING
# ============================================================

def check_node_numbering(node_ids):

    expected = np.arange(
        1,
        len(node_ids) + 1
    )

    if np.array_equal(
        node_ids,
        expected
    ):

        print(
            "Node numbering     : OK"
        )

    else:

        print(
            "Node numbering     : WARNING"
        )

        print(
            "Node IDs are not consecutively numbered."
        )


# ============================================================
# CHECK ELEMENT NUMBERING
# ============================================================

def check_element_numbering(element_ids):

    expected = np.arange(
        1,
        len(element_ids) + 1
    )

    if np.array_equal(
        element_ids,
        expected
    ):

        print(
            "Element numbering  : OK"
        )

    else:

        print(
            "Element numbering  : WARNING"
        )


# ============================================================
# CHECK CONNECTIVITY
# ============================================================

def check_connectivity(
        elements,
        number_of_nodes):

    node_min = np.min(
        elements
    )

    node_max = np.max(
        elements
    )

    if node_min < 1:

        raise ValueError(
            "Element connectivity contains node IDs < 1."
        )

    if node_max > number_of_nodes:

        raise ValueError(
            "Element connectivity contains undefined nodes."
        )

    print(
        "Connectivity        : OK"
    )


# ============================================================
# TRIANGULAR ELEMENT GEOMETRY
# ============================================================

def triangle_geometry(
        nodes,
        elements):

    number_of_elements = len(
        elements
    )

    centroids = np.zeros(
        (
            number_of_elements,
            3
        )
    )

    normals = np.zeros(
        (
            number_of_elements,
            3
        )
    )

    areas = np.zeros(
        number_of_elements
    )

    for e in range(
            number_of_elements):

        # Convert 1-based FEM numbering
        # to 0-based Python indexing

        n1, n2, n3 = (
            elements[e] - 1
        )

        p1 = nodes[n1]
        p2 = nodes[n2]
        p3 = nodes[n3]

        v1 = p2 - p1
        v2 = p3 - p1

        cross_product = np.cross(
            v1,
            v2
        )

        cross_norm = np.linalg.norm(
            cross_product
        )

        area = (
            0.5 *
            cross_norm
        )

        if cross_norm > AREA_TOL:

            normal = (
                cross_product /
                cross_norm
            )

        else:

            normal = np.zeros(
                3
            )

        centroid = (
            p1 +
            p2 +
            p3
        ) / 3.0

        centroids[e] = centroid
        normals[e] = normal
        areas[e] = area

    return (
        centroids,
        normals,
        areas
    )


# ============================================================
# DEGENERATE ELEMENT CHECK
# ============================================================

def check_element_areas(
        areas):

    bad_elements = np.where(
        areas <= AREA_TOL
    )[0]

    if len(
            bad_elements) == 0:

        print(
            "Element areas       : OK"
        )

    else:

        print(
            f"WARNING: "
            f"{len(bad_elements)} "
            f"degenerate elements detected."
        )

    return bad_elements


# ============================================================
# COMPUTE ELEMENT EDGE LENGTHS
# ============================================================

def compute_edge_lengths(
        nodes,
        elements):

    number_of_elements = len(
        elements
    )

    edge_lengths = np.zeros(
        (
            number_of_elements,
            3
        )
    )

    for e in range(
            number_of_elements):

        n1, n2, n3 = (
            elements[e] - 1
        )

        p1 = nodes[n1]
        p2 = nodes[n2]
        p3 = nodes[n3]

        edge_lengths[e, 0] = (
            np.linalg.norm(
                p2 - p1
            )
        )

        edge_lengths[e, 1] = (
            np.linalg.norm(
                p3 - p2
            )
        )

        edge_lengths[e, 2] = (
            np.linalg.norm(
                p1 - p3
            )
        )

    return edge_lengths


# ============================================================
# MESH QUALITY STATISTICS
# ============================================================

def mesh_quality_statistics(
        edge_lengths,
        areas):

    minimum_edge = np.min(
        edge_lengths
    )

    maximum_edge = np.max(
        edge_lengths
    )

    mean_edge = np.mean(
        edge_lengths
    )

    minimum_area = np.min(
        areas
    )

    maximum_area = np.max(
        areas
    )

    mean_area = np.mean(
        areas
    )

    print(
        "\nMesh-quality statistics"
    )

    print(
        "--------------------------------"
    )

    print(
        f"Minimum edge length : "
        f"{minimum_edge:.6e}"
    )

    print(
        f"Maximum edge length : "
        f"{maximum_edge:.6e}"
    )

    print(
        f"Mean edge length    : "
        f"{mean_edge:.6e}"
    )

    print(
        f"Minimum area        : "
        f"{minimum_area:.6e}"
    )

    print(
        f"Maximum area        : "
        f"{maximum_area:.6e}"
    )

    print(
        f"Mean area           : "
        f"{mean_area:.6e}"
    )


# ============================================================
# FIND BOUNDARY NODES
# ============================================================

def find_boundary_nodes(
        node_ids,
        nodes,
        Lx,
        Ly,
        Lz,
        tol):

    boundaries = {}

    boundaries["xmin"] = (
        node_ids[
            np.abs(
                nodes[:, 0]
            ) <= tol
        ]
    )

    boundaries["xmax"] = (
        node_ids[
            np.abs(
                nodes[:, 0] - Lx
            ) <= tol
        ]
    )

    boundaries["ymin"] = (
        node_ids[
            np.abs(
                nodes[:, 1]
            ) <= tol
        ]
    )

    boundaries["ymax"] = (
        node_ids[
            np.abs(
                nodes[:, 1] - Ly
            ) <= tol
        ]
    )

    boundaries["zmin"] = (
        node_ids[
            np.abs(
                nodes[:, 2]
            ) <= tol
        ]
    )

    boundaries["zmax"] = (
        node_ids[
            np.abs(
                nodes[:, 2] - Lz
            ) <= tol
        ]
    )

    return boundaries


# ============================================================
# PRINT BOUNDARY INFORMATION
# ============================================================

def print_boundary_information(
        boundaries):

    print(
        "\nBoundary-node sets"
    )

    print(
        "--------------------------------"
    )

    for name, ids in boundaries.items():

        print(
            f"{name:5s}: "
            f"{len(ids):6d} nodes"
        )


# ============================================================
# PERIODIC BOUNDARY COUNT CHECK
# ============================================================

def check_periodic_boundary_counts(
        boundaries):

    print(
        "\nPeriodic boundary count check"
    )

    print(
        "--------------------------------"
    )

    pairs = [
        (
            "xmin",
            "xmax"
        ),
        (
            "ymin",
            "ymax"
        ),
        (
            "zmin",
            "zmax"
        )
    ]

    for b1, b2 in pairs:

        n1 = len(
            boundaries[b1]
        )

        n2 = len(
            boundaries[b2]
        )

        if n1 == n2:

            status = "OK"

        else:

            status = "NOT MATCHING"

        print(
            f"{b1} <-> {b2}: "
            f"{n1} / {n2} "
            f"--> {status}"
        )


# ============================================================
# TOTAL SURFACE AREA
# ============================================================

def calculate_total_surface_area(
        areas):

    return np.sum(
        areas
    )


# ============================================================
# APPROXIMATE SHELL VOLUME
# ============================================================

def calculate_shell_volume(
        areas,
        thickness):

    surface_area = np.sum(
        areas
    )

    volume = (
        surface_area *
        thickness
    )

    return volume


# ============================================================
# APPROXIMATE SHELL MASS
# ============================================================

def calculate_shell_mass(
        areas,
        thickness,
        density):

    volume = (
        calculate_shell_volume(
            areas,
            thickness
        )
    )

    mass = (
        density *
        volume
    )

    return mass


# ============================================================
# EXPORT FEM NODE DATA
# ============================================================

def export_fem_nodes(
        filename,
        node_ids,
        nodes,
        normals):

    data = np.column_stack(
        (
            node_ids,
            nodes,
            normals
        )
    )

    np.savetxt(
        filename,
        data,
        delimiter=",",
        header=(
            "NodeID,"
            "X,Y,Z,"
            "NormalX,NormalY,NormalZ"
        ),
        comments="",
        fmt=[
            "%d",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e"
        ]
    )


# ============================================================
# EXPORT FEM ELEMENT DATA
# ============================================================

def export_fem_elements(
        filename,
        element_ids,
        elements,
        thickness):

    thickness_column = (
        np.ones(
            len(element_ids)
        ) *
        thickness
    )

    data = np.column_stack(
        (
            element_ids,
            elements,
            thickness_column
        )
    )

    np.savetxt(
        filename,
        data,
        delimiter=",",
        header=(
            "ElementID,"
            "Node1,Node2,Node3,"
            "Thickness"
        ),
        comments="",
        fmt=[
            "%d",
            "%d",
            "%d",
            "%d",
            "%.12e"
        ]
    )


# ============================================================
# EXPORT ELEMENT GEOMETRIC DATA
# ============================================================

def export_element_data(
        filename,
        element_ids,
        centroids,
        normals,
        areas):

    data = np.column_stack(
        (
            element_ids,
            centroids,
            normals,
            areas
        )
    )

    np.savetxt(
        filename,
        data,
        delimiter=",",
        header=(
            "ElementID,"
            "CentroidX,"
            "CentroidY,"
            "CentroidZ,"
            "NormalX,"
            "NormalY,"
            "NormalZ,"
            "Area"
        ),
        comments="",
        fmt=[
            "%d",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e",
            "%.12e"
        ]
    )


# ============================================================
# EXPORT BOUNDARY NODE SET
# ============================================================

def export_boundary_nodes(
        filename,
        node_ids):

    np.savetxt(
        filename,
        node_ids,
        delimiter=",",
        header="NodeID",
        comments="",
        fmt="%d"
    )


# ============================================================
# FEM MESH VISUALIZATION
# ============================================================

def plot_fem_mesh(
        nodes,
        elements,
        Lx,
        Ly,
        Lz,
        show_nodes=False,
        show_element_edges=True,
        mesh_alpha=0.70,
        edge_linewidth=0.25,
        node_size=2.0,
        elevation=25.0,
        azimuth=45.0):

    print(
        "\nPreparing interactive FEM mesh visualization..."
    )

    fig = plt.figure(
        figsize=(
            10,
            9
        )
    )

    ax = fig.add_subplot(
        111,
        projection="3d"
    )

    # --------------------------------------------------------
    # Convert FEM connectivity
    # --------------------------------------------------------

    elements_python = (
        elements - 1
    )

    triangles = (
        nodes[
            elements_python
        ]
    )

    # --------------------------------------------------------
    # Create triangular shell mesh
    # --------------------------------------------------------

    if show_element_edges:

        mesh = Poly3DCollection(
            triangles,
            alpha=mesh_alpha,
            edgecolor="black",
            linewidth=edge_linewidth
        )

    else:

        mesh = Poly3DCollection(
            triangles,
            alpha=mesh_alpha
        )

    ax.add_collection3d(
        mesh
    )

    # --------------------------------------------------------
    # Optional nodes
    # --------------------------------------------------------

    if show_nodes:

        ax.scatter(
            nodes[:, 0],
            nodes[:, 1],
            nodes[:, 2],
            s=node_size
        )

    # --------------------------------------------------------
    # Axis limits
    # --------------------------------------------------------

    ax.set_xlim(
        0.0,
        Lx
    )

    ax.set_ylim(
        0.0,
        Ly
    )

    ax.set_zlim(
        0.0,
        Lz
    )

    # --------------------------------------------------------
    # Axis labels
    # --------------------------------------------------------

    ax.set_xlabel(
        "X"
    )

    ax.set_ylabel(
        "Y"
    )

    ax.set_zlabel(
        "Z"
    )

    # --------------------------------------------------------
    # Equal aspect ratio
    # --------------------------------------------------------

    ax.set_box_aspect(
        (
            Lx,
            Ly,
            Lz
        )
    )

    # --------------------------------------------------------
    # Initial camera orientation
    # --------------------------------------------------------

    ax.view_init(
        elev=elevation,
        azim=azimuth
    )

    # --------------------------------------------------------
    # Enable mouse interaction
    # --------------------------------------------------------

    ax.mouse_init()

    ax.set_title(
        "Primitive TPMS - Shell FEM Mesh\n"
        "Click and drag to rotate"
    )

    plt.tight_layout()

    print(
        "\n3D viewer controls:"
    )

    print(
        "  Left mouse + drag : Rotate"
    )

    print(
        "  Scroll            : Zoom"
    )

    print(
        "  Right mouse + drag: Pan"
    )

    print(
        "  Home button       : Reset view"
    )

    plt.show()


# ============================================================
# MAIN PROGRAM
# ============================================================

def main():

    print(
        "============================================"
    )

    print(
        " TPMS Shell FEM Mesh Preprocessor"
    )

    print(
        "============================================"
    )

    # --------------------------------------------------------
    # READ INPUT DATA
    # --------------------------------------------------------

    print(
        "\nReading extracted TPMS geometry..."
    )

    node_ids, nodes = (
        read_nodes(
            NODE_FILE
        )
    )

    element_ids, elements = (
        read_elements(
            ELEMENT_FILE
        )
    )

    (
        normal_node_ids,
        nodal_normals
    ) = read_normals(
        NORMAL_FILE
    )

    print(
        f"Nodes loaded       : "
        f"{len(node_ids)}"
    )

    print(
        f"Elements loaded    : "
        f"{len(element_ids)}"
    )

    # --------------------------------------------------------
    # CHECK FEM DATA
    # --------------------------------------------------------

    print(
        "\nChecking FEM data"
    )

    print(
        "--------------------------------"
    )

    check_node_numbering(
        node_ids
    )

    check_element_numbering(
        element_ids
    )

    check_connectivity(
        elements,
        len(node_ids)
    )

    if not np.array_equal(
            node_ids,
            normal_node_ids):

        raise ValueError(
            "Normal-file node numbering does not "
            "match node-file numbering."
        )

    print(
        "Nodal normals       : OK"
    )

    # --------------------------------------------------------
    # ELEMENT GEOMETRY
    # --------------------------------------------------------

    print(
        "\nCalculating shell element geometry..."
    )

    (
        centroids,
        element_normals,
        areas
    ) = triangle_geometry(
        nodes,
        elements
    )

    check_element_areas(
        areas
    )

    # --------------------------------------------------------
    # EDGE LENGTHS
    # --------------------------------------------------------

    edge_lengths = (
        compute_edge_lengths(
            nodes,
            elements
        )
    )

    mesh_quality_statistics(
        edge_lengths,
        areas
    )

    # --------------------------------------------------------
    # GLOBAL GEOMETRIC DATA
    # --------------------------------------------------------

    total_surface_area = (
        calculate_total_surface_area(
            areas
        )
    )

    shell_volume = (
        calculate_shell_volume(
            areas,
            THICKNESS
        )
    )

    shell_mass = (
        calculate_shell_mass(
            areas,
            THICKNESS,
            RHO
        )
    )

    print(
        "\nTPMS shell information"
    )

    print(
        "--------------------------------"
    )

    print(
        f"Surface area       : "
        f"{total_surface_area:.8e}"
    )

    print(
        f"Approx. shell vol. : "
        f"{shell_volume:.8e}"
    )

    print(
        f"Approx. shell mass : "
        f"{shell_mass:.8e}"
    )

    # --------------------------------------------------------
    # MATERIAL INFORMATION
    # --------------------------------------------------------

    print(
        "\nMaterial properties"
    )

    print(
        "--------------------------------"
    )

    print(
        f"E         = "
        f"{E:.6e}"
    )

    print(
        f"nu        = "
        f"{NU:.6f}"
    )

    print(
        f"rho       = "
        f"{RHO:.6e}"
    )

    print(
        f"thickness = "
        f"{THICKNESS:.6e}"
    )

    # --------------------------------------------------------
    # BOUNDARY NODES
    # --------------------------------------------------------

    boundaries = (
        find_boundary_nodes(
            node_ids,
            nodes,
            Lx,
            Ly,
            Lz,
            BOUNDARY_TOL
        )
    )

    print_boundary_information(
        boundaries
    )

    check_periodic_boundary_counts(
        boundaries
    )

    # --------------------------------------------------------
    # EXPORT FEM DATA
    # --------------------------------------------------------

    print(
        "\nExporting FEM data..."
    )

    export_fem_nodes(
        OUTPUT_NODE_FILE,
        node_ids,
        nodes,
        nodal_normals
    )

    export_fem_elements(
        OUTPUT_ELEMENT_FILE,
        element_ids,
        elements,
        THICKNESS
    )

    export_element_data(
        OUTPUT_ELEMENT_DATA_FILE,
        element_ids,
        centroids,
        element_normals,
        areas
    )

    # --------------------------------------------------------
    # EXPORT BOUNDARY NODE SETS
    # --------------------------------------------------------

    export_boundary_nodes(
        OUTPUT_XMIN,
        boundaries["xmin"]
    )

    export_boundary_nodes(
        OUTPUT_XMAX,
        boundaries["xmax"]
    )

    export_boundary_nodes(
        OUTPUT_YMIN,
        boundaries["ymin"]
    )

    export_boundary_nodes(
        OUTPUT_YMAX,
        boundaries["ymax"]
    )

    export_boundary_nodes(
        OUTPUT_ZMIN,
        boundaries["zmin"]
    )

    export_boundary_nodes(
        OUTPUT_ZMAX,
        boundaries["zmax"]
    )

    # --------------------------------------------------------
    # OUTPUT INFORMATION
    # --------------------------------------------------------

    print(
        "\nGenerated files"
    )

    print(
        "--------------------------------"
    )

    print(
        OUTPUT_NODE_FILE
    )

    print(
        OUTPUT_ELEMENT_FILE
    )

    print(
        OUTPUT_ELEMENT_DATA_FILE
    )

    print(
        OUTPUT_XMIN
    )

    print(
        OUTPUT_XMAX
    )

    print(
        OUTPUT_YMIN
    )

    print(
        OUTPUT_YMAX
    )

    print(
        OUTPUT_ZMIN
    )

    print(
        OUTPUT_ZMAX
    )

    # --------------------------------------------------------
    # VISUALIZE FEM MESH
    # --------------------------------------------------------

    if SHOW_MESH:

        plot_fem_mesh(
            nodes,
            elements,
            Lx,
            Ly,
            Lz,
            show_nodes=SHOW_NODES,
            show_element_edges=SHOW_ELEMENT_EDGES,
            mesh_alpha=MESH_ALPHA,
            edge_linewidth=EDGE_LINEWIDTH,
            node_size=NODE_SIZE,
            elevation=VIEW_ELEVATION,
            azimuth=VIEW_AZIMUTH
        )

    print(
        "\nFinished."
    )


# ============================================================
# EXECUTE
# ============================================================

if __name__ == "__main__":
    main()